			}
			st := matchReviewSessionState(worktreeRoot, headSHA, summary.StartedAt, agentNameForRun(run), run.Model, states, usedSessions)
			if st == nil || st.SessionID == "" {
				continue
			}
			usedSessions[st.SessionID] = true
			matched[i] = st
		}
