}

// ExposedComposeMultiAgentSinks exposes composeMultiAgentSinks for tests.
func ExposedComposeMultiAgentSinks(in SinkComposeInputs) []reviewtypes.Sink {
	return composeMultiAgentSinks(multiAgentSinkInputs{
