// pickSlotList renders the single-screen add/edit/remove slot list used for both
// inspectors and judges. candidates are the agents offered when adding a slot;
// seed pre-populates the list. Returns at least one slot (Done is unavailable
// while empty).
func pickSlotList(ctx context.Context, title, desc string, candidates []string, seed []crewSlot) ([]crewSlot, error) {
	slots := append([]crewSlot(nil), seed...)
	const (
		actAdd     = "add"
		actDone    = "done"
		slotPrefix = "slot:"
	)
	for {
		options := make([]huh.Option[string], 0, len(slots)+2)
		for i, s := range slots {
			options = append(options, huh.NewOption(fmt.Sprintf("%d  %s", i+1, slotLabel(s)), slotPrefix+strconv.Itoa(i)))
		}
		options = append(options, huh.NewOption("+ Add", actAdd))
		if len(slots) > 0 {
			options = append(options, huh.NewOption(fmt.Sprintf("Done · %d", len(slots)), actDone))
		}
		picked := actDone
		if len(slots) == 0 {
			picked = actAdd
		}
		form := newAccessibleForm(huh.NewGroup(
			huh.NewSelect[string]().
				Title(title).
				Description(desc).
				Options(options...).
				Height(reviewPickerHeight(len(options))).
				Value(&picked),
		))
		if err := form.RunWithContext(ctx); err != nil {
			return nil, fmt.Errorf("slot picker: %w", err)
		}

		switch {
		case picked == actAdd:
			slot, err := promptCrewSlot(ctx, candidates, crewSlot{})
			if err != nil {
				return nil, err
			}
			slots = append(slots, slot)
		case picked == actDone:
			if len(slots) == 0 {
				continue
			}
			return slots, nil
		case strings.HasPrefix(picked, slotPrefix):
			idx, convErr := strconv.Atoi(strings.TrimPrefix(picked, slotPrefix))
			if convErr != nil || idx < 0 || idx >= len(slots) {
				continue
			}
			// Inspectors are identified by their agent and run on the agent's
			// default model, so editing only swaps the agent (when more than one is
			// available) or removes the slot — there is no per-inspector model.
			action, err := promptSlotAction(ctx, slots[idx], len(candidates) > 1)
			if err != nil {
				return nil, err
			}
			switch action {
			case "agent":
				slot, err := promptChangeAgent(ctx, candidates, slots[idx])
				if err != nil {
					return nil, err
				}
				slots[idx] = slot
			case "remove":
				slots = append(slots[:idx], slots[idx+1:]...)
			}
		}
	}
}

// promptCrewSlot prompts for one inspector slot: just the agent. Inspectors run
// on the agent's default model, so no model is asked here. seed pre-selects the
// current agent when editing (zero value when adding).
func promptCrewSlot(ctx context.Context, launchable []string, seed crewSlot) (crewSlot, error) {
	agentName, err := promptCrewAgent(ctx, launchable, seed.agent, false)
	if err != nil {
		return crewSlot{}, err
	}
	return crewSlot{agent: agentName}, nil
}

// promptChangeAgent swaps the agent on an existing inspector slot. Keeping the
// same agent leaves the slot untouched (preserving any model set via scripted
// config); choosing a different agent resets to that agent's default model.
func promptChangeAgent(ctx context.Context, candidates []string, seed crewSlot) (crewSlot, error) {
	agentName, err := promptCrewAgent(ctx, candidates, seed.agent, true)
	if err != nil {
		return crewSlot{}, err
	}
	if agentName == seed.agent {
		return seed, nil
	}
	return crewSlot{agent: agentName}, nil
}

// buildCrewProfile turns an ordered slot list into a profile. Each slot becomes
// a worker keyed by workerIDForAgentModel, which disambiguates duplicates
// (claude-code, claude-code-2, claude-code:opus, …).
func buildCrewProfile(ctx context.Context, profileName string, slots []crewSlot) settings.ReviewProfileConfig {
	profile := settings.ReviewProfileConfig{
		Task:   profileTask(profileName, settings.ReviewProfileConfig{}),
		Agents: make(map[string]settings.ReviewConfig, len(slots)),
	}
	for _, s := range slots {
		cfg := defaultReviewAgentConfig(profileName, s.agent)
		// Set Agent explicitly so the worker is valid even when the agent has no
		// default skills/prompt (e.g. Pi): IsZero is false once Agent is set, and
		// reviewAgentName resolves the real agent for the worker.
		cfg.Agent = s.agent
		cfg.Model = s.model
		profile.Agents[workerIDForAgentModel(s.agent, s.model, profile.Agents)] = cfg
	}
	// A default judge is only meaningful with more than one inspector;
	// RunReviewGuidedSetup re-asks for the judge in that case anyway.
	if len(profile.Agents) > 1 {
		if j, ok := defaultJudge(ctx, profile.Agents); ok {
			profile.Judge = &settings.ReviewConfig{Agent: j.agent, Model: j.model}
		}
	}
	return profile
}

// promptSlotAction asks what to do with an existing inspector slot row.
// Inspectors run on the agent's default model, so the only edits are swapping
// the agent (offered when allowAgentChange is set — more than one candidate
// exists) or removing the slot.
func promptSlotAction(ctx context.Context, slot crewSlot, allowAgentChange bool) (string, error) {
	options := make([]huh.Option[string], 0, 3)
	if allowAgentChange {
		options = append(options, huh.NewOption("Change agent", "agent"))
	}
	options = append(options,
		huh.NewOption("Remove", "remove"),
		huh.NewOption("Cancel", "cancel"),
	)
	picked := "cancel"
	form := newAccessibleForm(huh.NewGroup(
		huh.NewSelect[string]().
			Title(slotLabel(slot)).
			Options(options...).
			Value(&picked),
	))
	if err := form.RunWithContext(ctx); err != nil {
		return "", fmt.Errorf("slot action: %w", err)
	}
	return picked, nil
}

func slotLabel(s crewSlot) string {
	// Inspectors normally run on the agent's default model; only surface a model
	// when one was set explicitly (e.g. via scripted --set-slot).
	if model := strings.TrimSpace(s.model); model != "" {
		return labelForSimpleAgent(s.agent) + " · " + model
	}
	return labelForSimpleAgent(s.agent)
}

