func TestRunMulti_AllStartErrorsOverSeventeenStillFinish(t *testing.T) {
	t.Parallel()
	const reviewerCount = 32
	reviewers := make([]reviewtypes.AgentReviewer, 0, reviewerCount)
	for i := range reviewerCount {
