if err != nil {
	// No Process exists, so there is no Events/Wait lifecycle to preserve.
	// Classify before cancelAgent so a Start call that blocked until the
	// per-reviewer deadline keeps the reviewer-timeout cause visible. Then
	// cancel immediately to release the per-agent timeout timer while siblings
	// continue running. Queue the terminal marker so the dispatch loop remains
	// the single writer of perAgentState terminal fields.
	timedOut := reviewerDeadlineFired(ctx, agentCtx, err)
	cancelAgent()
	startTerminals = append(startTerminals, taggedEvent{agentIdx: i, terminal: &agentTerminal{
		startErr:   err,
		finishedAt: time.Now(),
		timedOut:   timedOut,
	}})
	continue
}

