	t.Parallel()
	rec := &stubSinkRecorder{}
	summary, err := Run(
		context.Background(),
		&startBlockingReviewer{name: "slow-start"},
		reviewtypes.RunConfig{ReviewerTimeout: 20 * time.Millisecond},
		[]reviewtypes.Sink{rec},
	)

