func buildTrailReviewCommentLocation(opts trailReviewCommentAddOptions) (api.TrailReviewLocationCreateRequest, error) {
	filePath := strings.TrimSpace(opts.FilePath)
	line := opts.Line
	if line < 0 || opts.StartLine < 0 || opts.EndLine < 0 {
