	t.Chdir(tmp)
	testutil.WriteFile(t, tmp, "src/app.go", "package main\nfunc main() {}\n")

	var gotBatch api.TrailReviewCommentBatchRequest
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
