+	if st == nil || st.SessionID == "" {
+		return run, ""
+	}
+	tokens := reviewTokensFromTokenUsage(reviewTokenUsageForSession(ctx, st, lookup))
+	if tokens.In == 0 && tokens.Out == 0 {
+		return run, st.SessionID
+	}
+	run.Tokens = tokens
+	return run, st.SessionID
+}
+
